    seq.playing=0; ui.rec=0;
    smc_ble_link(0); smc_poll(); assert(!smc.picked && !smc.seen && !smc.solo);
    smc_ble_link(1); smc_poll(); assert(!smc.picked && !smc.seen);
    if(getenv("SMC_PICKUP_ONLY")) return;
