/* SPDX-License-Identifier: GPL-3.0-only */
/* Chicago Fx Type = EQ — per-voice insert (not SEND / Mix theft).
 *
 * AU factory presets that use EQ (Bloghaus, Dist Sq Line, …) need a tilt shelf
 * on the dry 303 voice for strong-relative spectrum. Edit1 → tilt (dark↔bright
 * via one-pole LP vs HP residual); Edit2 → wet 0..1. No libm.
 *
 * Retune after #479: tip corner 120·50^t left Bloghaus Edit1=0 as a ~120 Hz LP
 * and grew strongRel (55.8→59.1 dB). Floor the corner at 750 Hz so dark EQ
 * still tilts without dumping the 303 body; bright map unchanged. */
#pragma once
#include <stdint.h>
#include "../dsp/fastmath.h"
#include "chicago_fx.h"

#ifndef CHI_EQ_SR
#define CHI_EQ_SR 44100.0f
#endif

typedef struct {
    float z;   /* one-pole LP state */
    float a;   /* LP feedback coeff */
    float g;   /* 1-a (feed) */
    float wet; /* 0 dry .. 1 full EQ */
    float tilt; /* 0 = dark (LP) .. 1 = bright (HP residual) */
} chi_eq_t;

static inline void chi_eq_set(chi_eq_t *e, uint8_t e1, uint8_t e2, float sr)
{
    float t, hz;
    if (sr < 1.0f)
        sr = CHI_EQ_SR;
    t = (float)e1 * (1.0f / 127.0f);
    /* Corner ~120 Hz .. ~6 kHz, floored at 750 Hz — tip dark extreme was too
     * low for Bloghaus/Dist SQ Line strong-relative spectrum. */
    hz = 120.0f * fm_powf(50.0f, t);
    if (hz < 750.0f)
        hz = 750.0f;
    e->a = fm_expf(-FM_TWO_PI * hz / sr);
    if (e->a > 0.999f)
        e->a = 0.999f;
    if (e->a < 0.0f)
        e->a = 0.0f;
    e->g = 1.0f - e->a;
    e->tilt = t;
    e->wet = (float)e2 * (1.0f / 127.0f);
}

static inline void chi_eq_init(chi_eq_t *e)
{
    e->z = 0.0f;
    e->a = 0.0f;
    e->g = 1.0f;
    e->wet = 0.0f;
    e->tilt = 0.5f;
}

/* In-place mono insert. wet=0 is a no-op. */
static inline void chi_eq_process(chi_eq_t *e, float *buf, int n)
{
    float z, a, g, wet, dry_g, tilt, inv_tilt;
    int k;
    if (!e || !buf || n <= 0)
        return;
    wet = e->wet;
    if (wet <= 0.0f)
        return;
    z = e->z;
    a = e->a;
    g = e->g;
    dry_g = 1.0f - wet;
    tilt = e->tilt;
    inv_tilt = 1.0f - tilt;
    for (k = 0; k < n; k++) {
        float x = buf[k];
        float lp, hp, shaped;
        z = a * z + g * x;
        lp = z;
        hp = x - z;
        /* Edit1 low → dark (LP); Edit1 high → bright (HP). Mid keeps body. */
        shaped = inv_tilt * lp + tilt * (x + hp);
        buf[k] = dry_g * x + wet * shaped;
    }
    e->z = z;
}

static inline int chi_fx_is_eq_insert(uint8_t type)
{
    return type == CHI_FX_EQ;
}

/* Execute the production main-loop editor/update block across transfer boundaries. */
#include <assert.h>
#include <stdint.h>
#include <stdio.h>

static struct { unsigned ota_req, uboot_req; } usb;
static struct { unsigned pending; } bootguard;
static uint32_t fm1_ms, ed_reboot_at;
static int busy, next_busy, inject_update, flash_ok = 1, seq, pending_ota;
static unsigned reboots, detaches, ota_polls, ota_entries, uboot_entries, stops;
enum { C_BLACK = 0 };

static int ui_project_busy(void) { return busy; }
static int ed_service(void)
{
    if (inject_update)
        usb.ota_req = usb.uboot_req = 1;
    if (next_busy >= 0)
        busy = next_busy;
    return pending_ota;
}
static void usb_detach(void) { detaches++; }
static void fm1_delay_ms(unsigned ms) { assert(ms == 30); }
static void fm1_reboot(void) { reboots++; }
static void ota_service(void) { ota_polls++; }
static void seq_stop(int *s) { assert(s == &seq); stops++; }
static void ota_session(void) { ota_entries++; }
static void lcd_fill(int x, int y, int w, int h, int c)
{
    assert(!x && !y && w == 240 && h == 240 && c == C_BLACK);
}
static void ui_init(void) {}
static void enter_uboot(const char *why) { assert(why); uboot_entries++; }

static void poll(void)
{
    int ota_pending;
#include "project_updates.inc"
}
static void reset(void)
{
    usb.ota_req = usb.uboot_req = 0;
    bootguard.pending = 1;
    fm1_ms = 1000;
    ed_reboot_at = 0;
    busy = inject_update = 0;
    next_busy = -1;
    pending_ota = 1;                                /* the editor peek left a non-editor frame */
    reboots = detaches = ota_polls = ota_entries = uboot_entries = stops = 0;
}

int main(void)
{
    reset();
    busy = 1;
    ed_reboot_at = 1;
    usb.ota_req = usb.uboot_req = 1;
    poll();
    assert(!reboots && !detaches && bootguard.pending && ed_reboot_at == 1);
    assert(!ota_polls && !ota_entries && !uboot_entries && !stops);
    assert(!usb.ota_req && !usb.uboot_req);
    busy = 0;
    poll();
    assert(reboots == 1 && detaches == 1 && !bootguard.pending);
    assert(!ota_entries && !uboot_entries);           /* cleared requests cannot replay */

    reset();
    next_busy = 1;                                  /* BEGIN acquires the hold in ed_service */
    inject_update = 1;
    ed_reboot_at = 1;
    poll();
    assert(busy && !reboots && !ota_polls && !ota_entries && !uboot_entries);
    assert(!usb.ota_req && !usb.uboot_req);

    reset();
    busy = 1;
    next_busy = 0;                                  /* COMMIT / ABORT releases the hold in ed_service */
    inject_update = 1;                              /* interrupt arrives while that handler runs */
    poll();
    assert(!busy && ota_polls == 1 && !ota_entries && !uboot_entries && !stops);
    assert(!usb.ota_req && !usb.uboot_req);

    reset();
    usb.ota_req = 1;
    poll();
    assert(ota_polls == 1 && ota_entries == 1 && stops == 1 && !usb.ota_req);
    reset();
    usb.uboot_req = 1;
    poll();
    assert(uboot_entries == 1);
    reset();
    ed_reboot_at = 800;                              /* retain the diagnostic reply's 200 ms grace */
    poll();
    assert(!reboots);
    fm1_ms++;
    poll();
    assert(reboots == 1);
    reset();
    pending_ota = 0;                                /* no non-editor frame from this editor check */
    poll();
    assert(!ota_polls && !ota_entries && !uboot_entries);
    puts("project_update_guard: held restart, BEGIN/COMMIT update discard and idle updates ok");
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Included by ble.c after the two role services. TIMER5 is the sole owner of
 * the host union and the mailbox consumer. Never restart the RF/core-1 image. */
static uint8_t ble_role_changing;
static uint32_t ble_role_at;

static void ble_service(void)
{
    uint8_t next = (uint8_t)(smc_ble_role_get() != 0);
    uint8_t addr[6];
    unsigned i;
    int stopped;
    if (ble_up && next != ble_central_role && !ble_role_changing) {
        ble_role_changing = 1;
        ble_role_at = fm1_ms;
    }
    if (ble_central_role) ble_central_service();
    else ble_device_service();
    if (!ble_up) return;
    if (next == ble_central_role) { ble_role_changing = 0; return; }
    if (ble_central_role)
        stopped = ble_r.host.c.state == BLEC_OFF;
    else
        stopped = !ble_link_st && !ble_r.host.h.cmd_wait &&
                  (ble_r.host.h.state == BLEH_IDLE ||
                   (ble_r.host.h.state == BLEH_ADVERTISING && !ble_r.host.h.want_adv));
    if (!stopped || xb_ring_used(&ble_r.mb.c2h) || xb_ring_used(&ble_r.mb.h2c)) {
        /* A controller that never acknowledges stop is not safe to reuse. */
        if (fm1_ms - ble_role_at >= 3000u) ble_fail();
        return;
    }
    for (i = 0; i < sizeof addr; i++)
        addr[i] = ble_central_role ? ble_r.host.c.addr[i] : ble_r.host.h.addr[i];
    ble_central_link_notify(0);
    smk_apc_ble_link(0, 0);
    ble_r.orr = ble_r.ow;
    ble_sx_n = ble_sx_over = ble_sx_reply = ble_sx_ch = 0;
    if (next)
        blec_init(&ble_r.host.c, ble_send, ble_central_midi, 0, addr);
    else {
        bleh_init(&ble_r.host.h, ble_send, 0, ble_r.nm, addr);
        bleh_set_sysex(&ble_r.host.h, ble_sysex_in);
    }
    ble_host_on = 0;  /* next tick starts the new role with its HCI Reset */
    ble_central_role = next;
    ble_role_changing = 0;
}
